import hashlib
import json

import asyncpg

DDL = """
CREATE TABLE IF NOT EXISTS api_keys (
  id BIGSERIAL PRIMARY KEY,
  key_id TEXT UNIQUE NOT NULL,
  key_hash TEXT UNIQUE NOT NULL,
  merchant_id TEXT NOT NULL,
  key_type TEXT NOT NULL CHECK (key_type IN ('secret','restricted','publishable')),
  scopes TEXT[] NOT NULL,
  allowed_origins TEXT[] NOT NULL DEFAULT '{}',
  active BOOLEAN NOT NULL DEFAULT TRUE
);
"""

def hash_key(pepper: str, raw_key: str) -> str:
    return hashlib.sha256(f"{pepper}:{raw_key}".encode()).hexdigest()

async def create_pool(dsn: str) -> asyncpg.Pool:
    return await asyncpg.create_pool(dsn, min_size=1, max_size=10)

async def init_db(pool: asyncpg.Pool, pepper: str, seed_json: str) -> None:
    async with pool.acquire() as conn:
        await conn.execute(DDL)
        for item in json.loads(seed_json):
            await conn.execute(
                """INSERT INTO api_keys (key_id,key_hash,merchant_id,key_type,scopes,allowed_origins,active)
                   VALUES ($1,$2,$3,$4,$5,$6,TRUE) ON CONFLICT (key_id) DO NOTHING""",
                item["key_id"], hash_key(pepper, item["raw_key"]), item["merchant_id"],
                item["key_type"], item["scopes"], item.get("allowed_origins", []),
            )

async def get_api_key(pool: asyncpg.Pool, pepper: str, raw_key: str) -> dict | None:
    async with pool.acquire() as conn:
        row = await conn.fetchrow(
            "SELECT key_id,merchant_id,key_type,scopes,allowed_origins,active FROM api_keys WHERE key_hash=$1",
            hash_key(pepper, raw_key),
        )
        return dict(row) if row else None
